#include <iostream>
#include <vector>

void ClampAll(std::vector<int>& values, int lo, int hi);

int main()
{
    int n, lo, hi;
    while (std::cin >> n >> lo >> hi)
    {
        std::vector<int> values(n);
        for (int i = 0; i < n; i++)
        {
            std::cin >> values[i];
        }
        ClampAll(values, lo, hi);
        for (int i = 0; i < n; i++)
        {
            std::cout << values[i] << (i + 1 < n ? " " : "");
        }
        std::cout << "\n";
    }
    return 0;
}

