"""Random vectors against a random [lo, hi] window, including lo == hi."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 12)
    lo = rng.randint(-10, 10)
    hi = lo + rng.choice([0, 0, rng.randint(1, 15)])
    values = [rng.randint(-30, 30) for _ in range(n)]
    return {"name": "%d values into [%d, %d] #%d" % (n, lo, hi, index),
            "stdin": "%d %d %d\n%s\n" % (n, lo, hi, " ".join(map(str, values)))}
